/**
 * Omni sweep wave 2 (2026-11-02): Unearthed Arcana — the book is a
 * variant-rules collection, so most of it yields no purchasable items.
 * What does: (1) the four sample legendary weapons of Chapter 5, each
 * with a printed "appears to be worth" market price (Dragonblade,
 * Hammer of All Souls, Ionon, Dreamstriker), built as magic items;
 * (2) Table 5–2's metamagic components — 576 spell rows were
 * enumerated; 50 rows list no component at all, 3 price the component
 * as "varies", and 13 use a complete standard weapon, shield, or
 * ammunition item priced as that item (e.g. a +1 quarterstaff for
 * changestaff) — those 66 rows were not built, leaving 510 priced
 * component records, built as equipment (the book prints no weights;
 * the listed cost is the minimum cost for the component). One row
 * (antimagic field) prints its cost without the "gp" unit; the
 * table's column is gp throughout. (3) The four sample drugs of
 * Table 6–12 and the taint-absorbing item (100 gp) of Chapter 6.
 * Not built: item familiars (an existing magic item of at least
 * 2,000 gp bonded by a feat — not a separate purchasable item),
 * incantations (rituals, not items), craft points / complex skills /
 * backgrounds (rules that merely price standard PHB and DMG goods in
 * their examples). Prices are the printed prices; summaries and
 * notes are mechanical effects in our own words.
 */
import type { EquipmentItem, MagicItemDefinition } from "@/engine/types";

